#![allow(unused_imports)]
use vstd::prelude::*;
verus! {

    // Computes, for a positive integer n days, the minimum and maximum
    // number of days‐off in any contiguous period of length n.
    //
    // Specification:
    //   * Requires n >= 1.
    //   * Returns a Vec of length 2: [min_off, max_off].
    //   * 0 <= min_off <= max_off <= n.
    //   * min_off == 2*floor(n/7) + max(0, (n mod 7) − 5).
    //   * max_off == 2*floor(n/7) + min(2, (n mod 7)).
    #[verifier(publish)]
    pub fn solve(n: i8) -> Vec<i8>
      requires
        n >= 1
      ensures
        |res: Vec<i8>| {
            res.len() == 2
            && 0 <= res[0]
            && res[0] <= res[1]
            && res[1] <= n
            && res[0] == 2*(n / 7) + std::cmp::max(0, n % 7 - 5)
            && res[1] == 2*(n / 7) + std::cmp::min(2, n % 7)
        }
    {
        // Compute the number of full weeks and the leftover days
        let week = n / 7;
        let r    = n % 7;
        // For positive n, 0 <= r < 7
        assert(r >= 0 && r <= 6);

        // Minimum extra days off from the leftover r days:
        //   if r > 5 then (r-5) else 0
        let min_add: i8 = if r - 5 > 0 { r - 5 } else { 0 };
        // Maximum extra days off from the leftover r days:
        //   if r < 2 then r else 2
        let max_add: i8 = if r < 2 { r } else { 2 };

        // Tie these back to the standard max/min functions
        assert(min_add == std::cmp::max(0, r - 5));
        assert(max_add == std::cmp::min(2, r));

        // Total minimum and maximum days off
        let min_off = 2 * week + min_add;
        let max_off = 2 * week + max_add;

        // Double‐check the final arithmetic matches the spec
        assert(min_off == 2*(n / 7) + std::cmp::max(0, r - 5));
        assert(max_off == 2*(n / 7) + std::cmp::min(2, r));

        // Build the result vector
        let mut res: Vec<i8> = Vec::new();
        res.push(min_off);
        res.push(max_off);

        // Final consistency checks
        assert(res.len() == 2);
        assert(res[0] == min_off);
        assert(res[1] == max_off);

        res
    }
}